import React, { useRef, useState } from "react";
import TimelineScroller from "./components/TimelineScroller";
import VideoPlayer from "./components/VideoPlayer";

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export default function App() {
  const fileInputRef = useRef(null);
  const videoRef = useRef(null);

  const [videoSrc, setVideoSrc] = useState("");
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [loading, setLoading] = useState(false);
  const [uploadError, setUploadError] = useState("");

  const openFilePicker = () => fileInputRef.current?.click();

  const handleFileChange = async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setUploadError("");

    try {
      const formData = new FormData();
      formData.append("video", file);

      const response = await fetch("http://localhost:5000/upload", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Upload failed");
      }

      const previewUrl = `http://localhost:5000${data.preview_video}`;

      setVideoSrc(previewUrl);
      setCurrentTime(0);
      setDuration(0);
    } catch (err) {
      setUploadError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePlay = () => {
    const video = videoRef.current;
    if (!video) return;

    if (video.paused) video.play();
    else video.pause();
  };

  const handleSeek = (time) => {
    const video = videoRef.current;
    if (!video || duration <= 0) return;

    const t = clamp(time, 0, duration);
    video.currentTime = t;
    setCurrentTime(t);
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-white py-10">
      <div className="w-full px-6">

        {/* HEADER */}
        <div className="mb-6 rounded-[24px] border border-white/10 bg-slate-950/95 p-6">
          <h1 className="text-xl font-semibold">Video Tampering Detection</h1>
          <p className="text-sm text-slate-400 mt-2">
            Upload a video to detect tampered segments.
          </p>

          <button
            onClick={openFilePicker}
            className="mt-4 px-4 py-2 bg-slate-800 rounded-md"
          >
            Upload Video
          </button>
        </div>

        {/* MAIN GRID */}
        <div className="grid gap-6 lg:grid-cols-[3fr_1fr] items-start">

          {/* LEFT SIDE */}
          <div className="flex flex-col gap-4">

            {/* VIDEO PANEL (FIXED HEIGHT) */}
            <div className="h-[520px] flex-shrink-0 overflow-hidden rounded-[20px] border border-white/10 bg-slate-950 p-4">
              <VideoPlayer
                ref={videoRef}
                src={videoSrc}
                isPlaying={isPlaying}
                currentTime={currentTime}
                onTogglePlay={handleTogglePlay}
                onTimeUpdate={setCurrentTime}
                onDurationChange={setDuration}
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
                hasVideo={!!videoSrc}
              />
            </div>

            {/* TIMELINE (SEPARATE — NO HEIGHT CONFLICT) */}
            <div className="timeline-panel rounded-[20px] border border-white/10 bg-slate-950 p-4">
              <TimelineScroller
                duration={duration}
                currentTime={currentTime}
                loading={loading}
                onSeek={handleSeek}
                onUploadClick={openFilePicker}
              />
            </div>

          </div>

          {/* RIGHT SIDE */}
          <div className="h-[520px] flex-shrink-0 flex flex-col rounded-[20px] border border-white/10 bg-slate-950 p-5">

            <div className="flex-1 flex flex-col justify-between">

              <div>
                <h2 className="text-lg font-semibold">Analysis</h2>
                <p className="text-sm text-slate-400 mt-2">
                  Detection results will appear here.
                </p>
              </div>

              <div className="space-y-4">
                <div className="bg-slate-800 p-3 rounded-md">
                  Duration:{" "}
                  {duration
                    ? `${Math.floor(duration / 60)
                        .toString()
                        .padStart(2, "0")}:${Math.floor(duration % 60)
                        .toString()
                        .padStart(2, "0")}`
                    : "00:00"}
                </div>

                <div className="bg-slate-800 p-3 rounded-md">
                  Status: {videoSrc ? "Ready" : "Waiting"}
                </div>
              </div>

              <div className="space-y-2">
                <button
                  disabled={!videoSrc}
                  className="w-full bg-slate-800 py-2 rounded-md"
                >
                  View Results
                </button>

                <button
                  disabled={!videoSrc}
                  className="w-full bg-slate-700 py-2 rounded-md"
                >
                  Download Report
                </button>
              </div>

            </div>
          </div>

        </div>

      </div>

      {/* FILE INPUT */}
      <input
        type="file"
        accept="video/*"
        ref={fileInputRef}
        className="hidden"
        onChange={handleFileChange}
      />

      {/* ERROR */}
      {uploadError && (
        <div className="text-red-400 text-center mt-4">
          {uploadError}
        </div>
      )}
    </div>
  );
}
